class Security(object):
    """
    The class corresponding to software page on selenium_sbts web, all operations under software
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver):
        self._service_account_ssh = ServiceAccountSshPage(driver)
        self._automatic_management = AutomaticManagementPage(driver)
        self._certificate_revocation_lists = CertificateRevocationListsPage(driver)
        self._vendor_certificates = VendorCertificatesPage(driver)
        self._netconf_radio_management = NetconfRadioManagementPage(driver)
        self._ip_security_association = IpSecurityAssociationsPage(driver)

    @property
    def service_account_ssh(self):
        return self._service_account_ssh

    @property
    def automatic_management(self):
        return self._automatic_management

    @property
    def certificate_revocation_lists(self):
        return self._certificate_revocation_lists

    @property
    def vendor_certificates(self):
        return self._vendor_certificates

    @property
    def netconf_radio_management(self):
        return self._netconf_radio_management

    @property
    def ip_security_association(self):
        return self._ip_security_association


class ServiceAccountSshPage(NavigatablePage):

    _MENU_ROUTE_LIST = ['Security', 'Service Account SSH']

    def __init__(self, driver):
        super(ServiceAccountSshPage, self).__init__(driver)
        self._view_panel = ServiceAccountSshPageViewPanel(driver)

    def enable_ssh_service(self, timeout):
        """
        Method for enabling ssh service under Service Account SSH page
        :param timeout: int, timeout
        :return: str, ssh service status after operating
        """
        return self._view_panel.enable_ssh_service(timeout)

    def disable_ssh_service(self, timeout):
        """
        Method for disabling ssh service under Service Account SSH page
        :param timeout: int, timeout
        :return: str, ssh service status after operating
        """
        return self._view_panel.disable_ssh_service(timeout)

