class ServiceAccountSshPageViewPanel(ViewPanel):
    _SERVICE_ACCOUNT_SSH_STATUS_XPATH = ('//div[@class="service-account-ssh-status-level"]'
                                         '//div[@class="service-account-ssh-status"]//span')
    _SERVICE_ACCOUNT_SSH_BUTTON_XPATH = ('//div[@class="service-account-ssh-status-level"]'
                                         '//div[@class="service-account-ssh-status"]//button')
    _SYNC_TO_RADIO_MODULES_BUTTON = '//div[*[contains(@class, "service-account-ssh-sync-ru")]]//button'
    _SYNC_RADIO_MODULES_STATUS = ('//div[*[contains(@class, "service-account-ssh-sync-ru")]]'
                                  '//*[@class="ui-inline-info"]//span[not(contains(@class, "icon"))]')
    ENABLED = 'Enabled'
    DISABLED = 'Disabled'
    SYNC_START = 'Synchronize radio modules start'
    SYNC_SUCCEEDED = 'Synchronize radio modules succeeded'

    def __init__(self, driver):
        super(ServiceAccountSshPageViewPanel, self).__init__(driver)

    def _change_ssh_to_expected_status(self, expected_status, timeout=60):
        self.click_enabled_element((By.XPATH, self._SERVICE_ACCOUNT_SSH_BUTTON_XPATH), timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._SERVICE_ACCOUNT_SSH_STATUS_XPATH),
                                              expected_status, timeout)
        return expected_status

    def _check_current_ssh_service_status(self, timeout=60):
        self.wait_for_visibility((By.XPATH, self._SERVICE_ACCOUNT_SSH_STATUS_XPATH), timeout)
        return self.get_text_by_xpath(self._SERVICE_ACCOUNT_SSH_STATUS_XPATH, timeout)

    def enable_ssh_service(self, timeout=60):
        if self.ENABLED == self._check_current_ssh_service_status(timeout):
            return self.ENABLED
        return self._change_ssh_to_expected_status(self.ENABLED, timeout)

    def disable_ssh_service(self, timeout=60):
        if self.DISABLED == self._check_current_ssh_service_status(timeout):
            return self.DISABLED
        return self._change_ssh_to_expected_status(self.DISABLED, timeout)

    def sync_to_radio_modules(self, timeout=60):
        self.wait_for_visibility_by_xpath(self._SYNC_TO_RADIO_MODULES_BUTTON)
        self.click_enabled_element((By.XPATH, self._SYNC_TO_RADIO_MODULES_BUTTON), timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._SYNC_RADIO_MODULES_STATUS),
                                              self.SYNC_START,
                                              timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._SYNC_RADIO_MODULES_STATUS),
                                              self.SYNC_SUCCEEDED,
                                              timeout)
        return self.SYNC_SUCCEEDED


