class AutomaticManagementPageViewPanel(ViewPanel):
    _REFERENCE_NUMBER_XPATH = "refNumber"
    _PRE_SHARED_KEY_XPATH = "psKey"
    _UPDATE_CMP_SERVER_BUTTON_XPATH = "//div[@class='cmp-update']//button"
    _UPDATE_CMP_SERVER_STATUS_XPATH = "//div[@class='cmp-update']//span[contains(@class,'icon')]"
    _INITIALIZE_CERTIFICATES_BUTTON_XPATH = ('//ui-button[@a-text="Initialize Certificates"]/button | '
                                             '//*[*[text()="Initialize Certificates"]]')
    _INITIALIZE_CERTIFICATES_STATUS_XPATH = ('//ui-button[@a-text="Initialize Certificates"]/following-sibling::div'
                                             '//span[contains(@class,"icon")] | '
                                             '//*[@*="Initialize Certificates"]/following-sibling::div//span[@class]')
    CMP_STATE_XPATH = '//*[@class="cmp-state"]/span'

    def __init__(self, driver):
        super(AutomaticManagementPageViewPanel, self).__init__(driver)

    def update_cmp_server_settings(self, reference_number, pre_shared_key):
        """
        Update CMP server settings at Automatic Management tab.
        :param reference_number: str, reference number
        :param pre_shared_key: str, per-shared key
        :return: boolean, True if succeed
        """
        filter_attribute = 'class'
        filter_attribute_text = 'icon-ok'

        self.insert_text_to_enabled_element((By.ID, self._REFERENCE_NUMBER_XPATH), reference_number, 5)
        self.insert_text_to_enabled_element((By.ID, self._PRE_SHARED_KEY_XPATH), pre_shared_key, 5)
        self.click_enabled_element((By.XPATH, self._UPDATE_CMP_SERVER_BUTTON_XPATH))
        self.wait_for_text_present_in_attribute(self._UPDATE_CMP_SERVER_STATUS_XPATH,
                                                filter_attribute, filter_attribute_text)

        update_cmp_server_status = self.get_attribute_by_xpath(self._UPDATE_CMP_SERVER_STATUS_XPATH, filter_attribute)
        return "ok" in update_cmp_server_status

    def initialize_certificates(self):
        """
        Initialize certificates at Automatic Management tab.
        :return: str, certificates initialized status
        """
        filter_attribute = 'class'
        filter_attribute_text = 'icon-ok'

        self.click_enabled_element((By.XPATH, self._INITIALIZE_CERTIFICATES_BUTTON_XPATH), 5)
        initialize_certificates_modal = InitializeCertificatesModal(self.driver)
        initialize_certificates_modal.wait_until_initialize_certificates_modal_appear()
        initialize_certificates_modal.initialize()
        self.wait_for_text_present_in_attribute(self._INITIALIZE_CERTIFICATES_STATUS_XPATH,
                                                filter_attribute, filter_attribute_text)

        initialize_certificates_status = self.get_attribute_by_xpath(self._INITIALIZE_CERTIFICATES_STATUS_XPATH,
                                                                     filter_attribute)
        return "ok" in initialize_certificates_status

    def get_cmp_state(self, timeout):
        """
        Get CMP state
        """
        return self.get_text_by_xpath(self.CMP_STATE_XPATH, timeout)


