class VendorCertificatesPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Vendor Certificates will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Security', 'Certificate Management', 'Vendor Certificates']
    _SN_CERTIFICATES_XPATH = "//vendor-certificates//tbody/tr/td[7]"

    def __init__(self, driver):
        super(VendorCertificatesPage, self).__init__(driver)
        self._view_panel = VendorCertificatesPageViewPanel(driver)
        self._detail_panel = VendorCertificatesPageDetailPanel(driver)

    def _get_detail_panel_info_vendor(self, element):
        self._detail_panel.expand_details_panel()
        element.click()
        return self._detail_panel.get_certificate_details_info()

    def _get_certificates_vendor(self):
        cert_info = {}
        cert_elements = self._view_panel.driver.find_elements_by_xpath(self._SN_CERTIFICATES_XPATH)
        for element in cert_elements:
            single_cert_info = {}
            try:
                element_serial_number = element.text.strip()
            except NoSuchElementException:
                element_serial_number = None
            if element_serial_number:
                single_cert_info[element_serial_number] = self._get_detail_panel_info_vendor(element)
                cert_info.update(single_cert_info)
        return cert_info

    def get_certificates_vendor(self, serial_number, timeout):
        cert_vendor_info = {}
        try:
            self._view_panel.expand_certificates_list_vendor(timeout)
        except TimeoutException:
            logging.warning("No certificate is found.")
            return cert_vendor_info

        cert_vendor_info.update(self._get_certificates_vendor())

        if serial_number in cert_vendor_info.keys():
            return {serial_number: cert_vendor_info[serial_number]}
        return cert_vendor_info

    def restore_vendor_certificates(self, timeout_for_restore):
        return self._view_panel.restore_vendor_certificates(timeout_for_restore)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


