class NetconfRadioManagementPageViewPanel(ViewPanel):
    _CIPHERS = 'Activate unsecure ciphers'
    _AUTH_METHOD = 'SSH server authentication method'
    _BTS_LEVEL_DROPDOWN_BUTTON = '//label[contains(text(), "{}")]/ancestor::*[@class="bts-conf"]//p-dropdown'
    _BTS_LEVEL_DROPDOWN_ITEM = _BTS_LEVEL_DROPDOWN_BUTTON + '//li'
    _ADD_ORU_ACCOUNT_BUTTON = '//button[*[contains(@class, "plus")]]'
    _ORUS = '//tr//*[contains(text(), "SSDORU")]'
    _ORU_BASE_XPATH = '//*[contains(text(), "{}")]/ancestor::tr'
    _TARGET_ORU = _ORU_BASE_XPATH + '//*[@class="account-name"]'
    _DELETE_ORU_BUTTON = _ORU_BASE_XPATH + '//button[contains(@class, "delete")]'
    _ACCOUNT_NAME = '//*[@id="account-name"]'
    _ACCOUNT_PASSWORD = '//*[@id="account-pwd"]'
    _CONFIRM_ACCOUNT_PASSWORD = '//*[@id="confirm-account-pwd"]'
    _ADDITIONAL_NETCONF_ACCOUNT_BUTTON = '//*[contains(text(), "Configure Additional Netconf Account")]/parent::button'
    _DELETE_ADDITIONAL_NETCONF_ACCOUNT_BUTTON = ('//div[*[contains(text(), "Additional netconf account")]]'
                                                 '//button[@class="account-button"]')
    _ADDITIONAL_NETCONF_ACCOUNT_NAME = '//*[@id="additional-netconf-account-name"]'
    _ADDITIONAL_NETCONF_ACCOUNT_PWD = '//*[@id="additional-netconf-account-pwd"]'
    _CONFIRM_ADDITIONAL_NETCONF_ACCOUNT_PWD = '//*[@id="confirm-additional-netconf-account-pwd"]'
    _SSH_SERVER_HOST_PUBLIC_KEY_FORMAT_IDENTIFIER = '//*[@id="ssh-server-host-public-key-format-identifier"]'
    _SSH_SERVER_HOST_PUBLIC_KEY_VALUE = '//*[@id="ssh-server-host-public-key-value"]'
    _ORU_TARGERDN = '//*[@id="oru-targerDN"]'
    _SEND_BUTTON = '//div[@class="send-button"]//button'
    _SEND_OUTCOME = '//div[@class="send-button"]//*[contains(@class, "excute-msg")]'
    _CONFIGURING = 'Configuring netconf radio'
    _LOAD_PROFILE_BUTTON = '//button[*[text()="Load Profile"]]'

    def __init__(self, driver):
        super(NetconfRadioManagementPageViewPanel, self).__init__(driver)

    def send_netconf_configuration(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._SEND_BUTTON), timeout)
        self.wait_for_text_present_in_element((By.XPATH, self._SEND_OUTCOME), self._CONFIGURING, timeout)
        self.wait_for_text_not_present_in_element((By.XPATH, self._SEND_OUTCOME), self._CONFIGURING, timeout)
        return self.get_text_by_xpath(self._SEND_OUTCOME, timeout)

    def configure_bts_level(self, cipher='false', auth_method='No authentication', timeout=60):
        self.select_element_from_dropdown_list_by_text_and_click(
            cipher,
            (By.XPATH, self._BTS_LEVEL_DROPDOWN_BUTTON.format(self._CIPHERS)),
            (By.XPATH, self._BTS_LEVEL_DROPDOWN_ITEM.format(self._CIPHERS)),
            timeout
        )

        elems = self.expand_dropdown_list_and_return_elements(
            (By.XPATH, self._BTS_LEVEL_DROPDOWN_BUTTON.format(self._AUTH_METHOD)),
            (By.XPATH, self._BTS_LEVEL_DROPDOWN_ITEM.format(self._AUTH_METHOD))
        )
        self.find_element_from_group_by_text(elems, auth_method).click()

        change_method_modal = ChangeAuthenticationMethodModal(self.driver)
        try:
            change_method_modal.wait_for_method_change_modal_appear()
            change_method_modal.confirm()
        except TimeoutException:
            return

    def _get_current_exist_oru(self):
        elems = self.driver.find_elements_by_xpath(self._ORUS)
        return [elem.text.strip() for elem in elems]

    def add_oru_account(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._ADD_ORU_ACCOUNT_BUTTON), timeout)
        return self._get_current_exist_oru()[-1]

    def delete_oru_account(self, oru_name, timeout=60):
        self.click_enabled_element((By.XPATH, self._DELETE_ORU_BUTTON.format(oru_name)), timeout)
        self._get_current_exist_oru()

    def configure_default_netconf_account(self, oru_name, account_name, account_pwd, confirm_account_pwd, timeout=60):
        self.wait_for_visibility_by_xpath(self._TARGET_ORU.format(oru_name))
        self.click_enabled_element((By.XPATH, self._TARGET_ORU.format(oru_name)), timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._ACCOUNT_NAME), account_name, timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._ACCOUNT_PASSWORD), account_pwd, timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._CONFIRM_ACCOUNT_PASSWORD), confirm_account_pwd, timeout)

    def configure_additional_netconf_account(self, oru_name, account_name, account_pwd,
                                             confirm_account_pwd, timeout=60):
        self.click_enabled_element((By.XPATH, self._TARGET_ORU.format(oru_name)), timeout)
        self.click_enabled_element((By.XPATH, self._ADDITIONAL_NETCONF_ACCOUNT_BUTTON), timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._ADDITIONAL_NETCONF_ACCOUNT_NAME), account_name, timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._ADDITIONAL_NETCONF_ACCOUNT_PWD), account_pwd, timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._CONFIRM_ADDITIONAL_NETCONF_ACCOUNT_PWD),
                                            confirm_account_pwd,
                                            timeout)

    def delete_additional_netconf_account(self, oru_name, timeout=60):
        self.click_enabled_element((By.XPATH, self._TARGET_ORU.format(oru_name)), timeout)
        self.click_enabled_element((By.XPATH, self._DELETE_ADDITIONAL_NETCONF_ACCOUNT_BUTTON), timeout)

    def configure_oru_target_distname(self, oru_name, oru_target_dist_name, timeout=60):
        self.click_enabled_element((By.XPATH, self._TARGET_ORU.format(oru_name)), timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._ORU_TARGERDN), oru_target_dist_name, timeout)

    def configure_authentifier_ssh_server(self, oru_name, public_key_identifier, public_key_value, timeout=60):
        self.click_enabled_element((By.XPATH, self._TARGET_ORU.format(oru_name)), timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._SSH_SERVER_HOST_PUBLIC_KEY_FORMAT_IDENTIFIER),
                                            public_key_identifier,
                                            timeout)
        self.insert_text_to_enabled_element((By.XPATH, self._SSH_SERVER_HOST_PUBLIC_KEY_VALUE), public_key_value,
                                            timeout)

    def load_netconf_profile(self, file_path, apply_for_warning, timeout=60):
        self.click_enabled_element((By.XPATH, self._LOAD_PROFILE_BUTTON), timeout)
        load_raml_profile_modal = LoadRamlProfileModal(self.driver)
        load_raml_profile_modal.wait_until_load_raml_profile_modal_appear(timeout)
        load_raml_profile_modal.upload_profile(file_path, timeout)
        status = load_raml_profile_modal.apply(apply_for_warning, timeout)
        return status


